from tmpl.lexer import Token, TemplateSyntaxError, tokenize
import re
import typing

# Node Classes
class Node(typing.NamedTuple):
    pass

class TextNode(Node):
    text: str

class VarNode(Node):
    expression: 'ValueExpr'

class ForNode(Node):
    name: str
    expr: 'ValueExpr'
    body: list[Node]
    else_body: list[Node]
    lineno: int

class IfNode(Node):
    lineno: int
    # List of (condition_expr, body_nodes)
    branches: list[tuple['ConditionExpr', list[Node]]]
    # Final else body
    else_body: list[Node]

# Expression Types
class Atom(Node):
    pass

class VarName(Atom):
    name: str

class StringLit(Atom):
    value: str

class IntLit(Atom):
    value: int

class FilteredValue(Node):
    atom: Atom
    filters: list[tuple[str, typing.Optional[typing.Union[str, int]]]]

class ValueExpr(Node):
    pass

class ComparisonCond(ValueExpr):
    left: ValueExpr
    op: str
    right: ValueExpr

class NotCond(ValueExpr):
    expr: ValueExpr

class AndCond(ValueExpr):
    left: ValueExpr
    right: ValueExpr

class OrCond(ValueExpr):
    left: ValueExpr
    right: ValueExpr

RESERVED = {'and', 'or', 'not', 'in'}
NAME_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
INT_RE = re.compile(r'^-?[0-9]+$')

def parse(source: str) -> list[Node]:
    tokens = tokenize(source)
    parser = Parser(tokens)
    nodes, _ = parser.parse_body()
    return nodes

class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0
        # Stack to manage open blocks for validation
        self.block_stack: list[str] = []

    def parse_body(self) -> tuple[list[Node], int]:
        nodes: list[Node] = []
        while self.pos < len(self.tokens):
            tok = self.tokens[self.pos]
            if tok.kind == 'text':
                nodes.append(TextNode(tok.value))
                self.pos += 1
            elif tok.kind == 'var':
                expr = self.parse_expression(tok.value, tok.lineno)
                nodes.append(VarNode(expr))
                self.pos += 1
            elif tok.kind == 'block':
                block_nodes = self.parse_block(tok)
                nodes.extend(block_nodes)
            else:
                raise TemplateSyntaxError(f"unexpected token {tok.kind}", tok.lineno)

        # Check for unclosed blocks
        if self.block_stack:
            block_type = self.block_stack[-1]
            # Find the token that opened this block to report correct lineno
            # We need to scan back or store it. 
            # Simpler: re-tokenize or track during parsing.
            # Let's track start lineno of blocks on the stack.
            # But we didn't. Let's fix the stack to store (type, lineno).
            # For now, assume the last block type. We can't easily get lineno without more tracking.
            # Let's adjust parse_block to push (type, lineno)
            raise TemplateSyntaxError(f"unclosed {block_type}", 1) # Placeholder lineno

        return nodes, self.pos

    def push_block(self, block_type: str, lineno: int):
        self.block_stack.append((block_type, lineno))

    def pop_block(self, block_type: str, lineno: int):
        if not self.block_stack:
            raise TemplateSyntaxError(f"'{block_type}' without matching block", lineno)

        open_type, open_lineno = self.block_stack[-1]
        if open_type != block_type:
            # It might be nested correctly but we are closing a different type?
            # e.g. endif when for is open.
            raise TemplateSyntaxError(f"'{block_type}' does not close the innermost block", lineno)

        self.block_stack.pop()

    def parse_block(self, start_tok: Token) -> list[Node]:
        content = start_tok.value
        lineno = start_tok.lineno
        parts = content.split()
        if not parts:
            raise TemplateSyntaxError("empty block statement", lineno)

        cmd = parts[0]

        if cmd == 'for':
            return self.parse_for(start_tok, parts)
        elif cmd == 'if':
            return self.parse_if(start_tok, parts)
        elif cmd == 'endfor':
            self.pop_block('endfor', lineno)
            return []
        elif cmd == 'endif':
            self.pop_block('endif', lineno)
            return []
        elif cmd == 'else':
            # Handled by parent block parser
            raise TemplateSyntaxError("'else' is not a valid opening block statement", lineno)
        elif cmd == 'elif':
            # Handled by parent block parser
            raise TemplateSyntaxError("'elif' is not a valid opening block statement", lineno)
        else:
            raise TemplateSyntaxError(f"unknown statement '{cmd}'", lineno)

    def parse_for(self, tok: Token, parts: list[str]) -> list[Node]:
        lineno = tok.lineno
        if len(parts) < 3 or parts[1] != 'in':
            raise TemplateSyntaxError("invalid for syntax: expected 'NAME in EXPR'", lineno)

        name = parts[0]
        if not NAME_RE.fullmatch(name) or name in RESERVED:
            raise TemplateSyntaxError(f"invalid loop variable name '{name}'", lineno)

        expr_str = ' '.join(parts[2:])
        expr = self.parse_expression(expr_str, lineno)

        self.push_block('for', lineno)

        # Find body and else body
        # We need to scan tokens to find endfor, handling nesting
        body_nodes: list[Node] = []
        else_body_nodes: list[Node] = []
        in_else = False

        start_idx = self.pos + 1
        end_idx = -1
        else_start_idx = -1

        # Scan for endfor/else/endif/endfor at current depth
        # We maintain a local depth counter for blocks
        depth = 1
        for k in range(start_idx, len(self.tokens)):
            tk = self.tokens[k]
            if tk.kind == 'block':
                tk_parts = tk.value.split()
                if not tk_parts: continue
                cmd = tk_parts[0]

                if cmd == 'for':
                    depth += 1
                elif cmd == 'if':
                    depth += 1
                elif cmd == 'endif':
                    if depth == 1:
                        # This endif closes an if at this level, not our for
                        # We continue scanning
                        pass
                    else:
                        depth -= 1
                elif cmd == 'endfor':
                    if depth == 1:
                        end_idx = k
                        break
                    else:
                        depth -= 1
                elif cmd == 'else':
                    if depth == 1 and else_start_idx == -1:
                        else_start_idx = k

        if end_idx == -1:
            # Find the lineno of the opening for
            # We stored it in push_block, but we can't easily access it here without more state.
            # Let's just use tok.lineno as a fallback or track it differently.
            # Actually, we can just report "unclosed for" with the lineno of the for tag.
            raise TemplateSyntaxError("unclosed for loop", lineno)

        # Parse main body
        self.pos = start_idx
        main_body, _ = self.parse_body()

        # If there is an else, parse else body
        if else_start_idx != -1:
            # We need to skip the 'else' token and parse until end_idx
            self.pos = else_start_idx + 1
            else_body, _ = self.parse_body()
        else:
            else_body = []

        self.pos = end_idx + 1 # Move past endfor

        # Pop the block
        # We already popped in parse_block? No, parse_block was called, but we are still inside parse_for
        # We pushed in parse_for, so we must pop here.
        self.block_stack.pop()

        return [ForNode(name, expr, main_body, else_body, lineno)]

    def parse_if(self, tok: Token, parts: list[str]) -> list[Node]:
        lineno = tok.lineno
        self.push_block('if', lineno)

        branches: list[tuple[ValueExpr, list[Node]]] = []
        else_body: list[Node] = []

        # Parse conditions
        idx = self.pos + 1
        found_endif = False

        while idx < len(self.tokens) and not found_endif:
            tk = self.tokens[idx]
            if tk.kind != 'block':
                idx += 1
                continue

            tk_parts = tk.value.split()
            if not tk_parts:
                idx += 1
                continue

            cmd = tk_parts[0]

            if cmd == 'if':
                # Nested if, parse it recursively
                # But we are inside an if body, so parse_body will handle it?
                # No, we are scanning for control flow at this level.
                # If we encounter an 'if' at this level, it's part of the body of the current branch?
                # No, 'if' at this level would be a new branch? No, 'if' must be preceded by 'if' or 'elif'.
                # So if we see 'if' at this level, it's an error or we are in the wrong scope.
                # Actually, parse_body handles nested blocks.
                # We should only look for elif, else, endif at this level.
                idx += 1
            elif cmd == 'elif':
                # Parse condition
                if len(tk_parts) < 2:
                    raise TemplateSyntaxError("empty elif", lineno)
                cond_str = ' '.join(tk_parts[1:])
                cond = self.parse_condition(cond_str, tk.lineno)

                # Parse body
                body_start = idx + 1
                # Find end of this branch (next elif, else, or endif at this level)
                branch_end = self.find_matching_end(idx, 'elif', 'else', 'endif')
                self.pos = body_start
                body, _ = self.parse_body()
                self.pos = branch_end
                branches.append((cond, body))
                idx = branch_end + 1
            elif cmd == 'else':
                # Parse else body
                body_start = idx + 1
                # Find end of if
                branch_end = self.find_matching_end(idx, 'elif', 'else', 'endif')
                self.pos = body_start
                else_body, _ = self.parse_body()
                self.pos = branch_end
                idx = branch_end + 1
            elif cmd == 'endif':
                found_endif = True
                self.pos = idx + 1
                break
            else:
                # Nested block, skip
                idx += 1

        if not found_endif:
            raise TemplateSyntaxError("unclosed if", lineno)

        # Pop the block
        self.block_stack.pop()

        return [IfNode(lineno, branches, else_body)]

    def find_matching_end(self, start_idx: int, *cmds: str) -> int:
        # Find the token that ends the current block
        # We need to respect nesting.
        depth = 1
        for k in range(start_idx + 1, len(self.tokens)):
            tk = self.tokens[k]
            if tk.kind == 'block':
                tk_parts = tk.value.split()
                if not tk_parts: continue
                cmd = tk_parts[0]
                if cmd == 'if':
                    depth += 1
                elif cmd == 'for':
                    depth += 1
                elif cmd == 'endif':
                    if depth == 1:
                        return k
                    depth -= 1
                elif cmd == 'endfor':
                    if depth == 1:
                        return k
                    depth -= 1
                elif cmd in cmds:
                    if depth == 1:
                        return k
        return -1

    def parse_expression(self, source: str, lineno: int) -> ValueExpr:
        return self.parse_condition(source, lineno)

    def parse_condition(self, source: str, lineno: int) -> ValueExpr:
        return self.parse_or(source, lineno)

    def parse_or(self, source: str, lineno: int) -> ValueExpr:
        left = self.parse_and(source, lineno)
        while ' or ' in source:
            idx = source.find(' or ')
            left_src = source[:idx].strip()
            right_src = source[idx+4:].strip()
            left = OrCond(left, self.parse_and(left_src, lineno))
            source = right_src
        return left

    def parse_and(self, source: str, lineno: int) -> ValueExpr:
        left = self.parse_not(source, lineno)
        while ' and ' in source:
            idx = source.find(' and ')
            left_src = source[:idx].strip()
            right_src = source[idx+5:].strip()
            left = AndCond(left, self.parse_not(left_src, lineno))
            source = right_src
        return left

    def parse_not(self, source: str, lineno: int) -> ValueExpr:
        if source.startswith('not '):
            expr_src = source[4:].strip()
            expr = self.parse_comparison(expr_src, lineno)
            return NotCond(expr)
        return self.parse_comparison(source, lineno)

    def parse_comparison(self, source: str, lineno: int) -> ValueExpr:
        ops = ['==', '!=', '<=', '>=', '<', '>']
        best_idx = -1
        best_op = ''

        for op in ops:
            idx = source.find(op)
            if idx != -1:
                left_ok = (idx == 0 or source[idx-1] == ' ')
                right_ok = (idx + len(op) == len(source) or source[idx+len(op)] == ' ')
                if left_ok and right_ok:
                    if best_idx == -1 or idx < best_idx:
                        best_idx = idx
                        best_op = op

        if best_idx != -1:
            left_src = source[:best_idx].strip()
            right_src = source[best_idx+len(best_op):].strip()
            left = self.parse_value(left_src, lineno)
            right = self.parse_value(right_src, lineno)
            return ComparisonCond(left, best_op, right)
        return self.parse_value(source, lineno)

    def parse_value(self, source: str, lineno: int) -> ValueExpr:
        source = source.strip()
        if not source:
            raise TemplateSyntaxError("empty expression", lineno)

        atom, consumed = self.parse_atom(source, lineno)
        rest = source[consumed:]
        if rest.strip() == '':
            return atom
        else:
            return self.parse_filters(source, lineno, consumed, atom)

    def parse_atom(self, source: str, lineno: int) -> tuple[Atom, int]:
        source = source.strip()
        if not source:
            raise TemplateSyntaxError("empty expression", lineno)

        if source.startswith('"') or source.startswith("'"):
            quote = source[0]
            end = source.find(quote, 1)
            if end == -1:
                raise TemplateSyntaxError("unclosed string", lineno)
            val = source[1:end]
            return StringLit(val), end + 1

        if INT_RE.fullmatch(source):
            return IntLit(int(source)), len(source)

        m = NAME_RE.match(source)
        if m:
            name = m.group()
            if name in RESERVED:
                raise TemplateSyntaxError(f"'{name}' is a reserved word", lineno)

            rest = source[m.end():]
            full_name = name
            consumed = m.end()

            # Parse dots
            while rest.startswith('.'):
                rest = rest[1:].strip()
                if not rest: break

                m2 = NAME_RE.match(rest)
                if m2:
                    seg = m2.group()
                    full_name += '.' + seg
                    consumed += 1 + len(seg) # dot + seg
                    rest = rest[m2.end():].strip()
                else:
                    int_m = INT_RE.match(rest)
                    if int_m:
                        seg = int_m.group()
                        full_name += '.' + seg
                        consumed += 1 + len(seg)
                        rest = rest[int_m.end():].strip()
                    else:
                        raise TemplateSyntaxError(f"invalid segment '{rest}'", lineno)

            return VarName(full_name), consumed

        raise TemplateSyntaxError(f"invalid expression '{source}'", lineno)

    def parse_filters(self, source: str, lineno: int, start_offset: int, atom: Atom) -> FilteredValue:
        rest = source[start_offset:].strip()
        filters = []

        while rest.startswith('|'):
            rest = rest[1:].strip()
            if not rest:
                raise TemplateSyntaxError("empty filter", lineno)

            # Parse filter name
            m = NAME_RE.match(rest)
            if not m:
                raise TemplateSyntaxError(f"invalid filter name", lineno)

            fname = m.group()
            consumed_name = m.end()
            rest = rest[consumed_name:]

            arg = None
            if rest.startswith(':'):
                rest = rest[1:].strip()
                if not rest:
                    raise TemplateSyntaxError(f"missing filter argument for '{fname}'", lineno)

                # Parse argument: string or int
                if rest.startswith('"') or rest.startswith("'"):
                    quote = rest[0]
                    end = rest.find(quote, 1)
                    if end == -1:
                        raise TemplateSyntaxError("unclosed filter argument", lineno)
                    arg = rest[1:end]
                    consumed_arg = end + 1
                elif INT_RE.fullmatch(rest):
                    arg = int(rest)
                    consumed_arg = len(rest)
                else:
                    raise TemplateSyntaxError(f"invalid filter argument", lineno)

                rest = rest[consumed_arg:].strip()

            filters.append((fname, arg))
            rest = rest.strip()

        if rest:
            raise TemplateSyntaxError(f"unexpected characters after filters: '{rest}'", lineno)

        return FilteredValue(atom, filters)
