import typing


class TemplateError(Exception):
    """Base exception for template errors."""
    pass


class TemplateSyntaxError(TemplateError):
    """Syntax error in the template."""
    def __init__(self, message: str, lineno: int):
        self.message = message
        self.lineno = lineno
        super().__init__(f"line {lineno}: {message}")


class TemplateRenderError(TemplateError):
    """Render error during execution."""
    def __init__(self, message: str, lineno: int):
        self.message = message
        self.lineno = lineno
        super().__init__(f"line {lineno}: {message}")


class Token(typing.NamedTuple):
    kind: str
    value: str
    lineno: int


def tokenize(source: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(source)
    current_line = 1

    # We need to track the start line of the current text run
    text_start_line = 1
    prev_i = 0

    while i < n:
        # Check for potential tag start
        if i + 1 < n and source[i] == '{':
            next_char = source[i+1]
            if next_char in ('{', '%', '#'):
                # It's a tag
                prefix = source[i:i+2]
                start_line = current_line

                # Determine end delimiter
                if prefix == '{{':
                    end_delim = '}}'
                elif prefix == '{%':
                    end_delim = '%}'
                else:
                    end_delim = '#}'

                # Find closing delimiter
                end_idx = source.find(end_delim, i + 2)
                if end_idx == -1:
                    # Count newlines in the rest of the string to update line counter correctly
                    current_line += source[i+2:].count('\n')
                    if prefix == '{#':
                        raise TemplateSyntaxError("unclosed comment", start_line)
                    else:
                        raise TemplateSyntaxError(f"unclosed {prefix}", start_line)

                # Calculate line number of the end of the tag for updating current_line
                # We need to count newlines in source[i:end_idx+2]
                tag_span = source[i:end_idx+2]
                current_line += tag_span.count('\n')

                # Extract text before this tag
                text = source[prev_i:i]
                if text:
                    tokens.append(Token('text', text, text_start_line))

                # Extract tag content
                raw_tag_content = source[i+2:end_idx]
                stripped_tag_content = raw_tag_content.strip()

                if prefix == '{#':
                    # Comment, do not emit token
                    pass
                elif prefix == '{{':
                    tokens.append(Token('var', stripped_tag_content, start_line))
                elif prefix == '{%':
                    tokens.append(Token('block', stripped_tag_content, start_line))

                prev_i = end_idx + 2
                i = end_idx + 2
                # The next text token will start on the current_line (which is now the line of the char after the tag)
                text_start_line = current_line
                continue

        # Advance one char
        if source[i] == '\n':
            current_line += 1
        i += 1

    # Remaining text
    if prev_i < n:
        text = source[prev_i:]
        if text:
            tokens.append(Token('text', text, text_start_line))

    return tokens
