from tmpl.parser import parse, TextNode, VarNode, ForNode, IfNode, FilteredValue, VarName, StringLit, IntLit, ValueExpr, ComparisonCond, NotCond, AndCond, OrCond
from tmpl.lexer import TemplateRenderError
import collections.abc

def render(source: str, context: dict | None = None, **kwargs) -> str:
    return Template(source).render(context, **kwargs)

class Template:
    def __init__(self, source: str):
        self.nodes = parse(source)

    def render(self, context: dict | None = None, **kwargs) -> str:
        if context is None:
            ctx = {}
        else:
            ctx = dict(context)
        ctx.update(kwargs)
        return self._render_nodes(self.nodes, ctx)

    def _render_nodes(self, nodes: list, ctx: dict) -> str:
        res = []
        for node in nodes:
            if isinstance(node, TextNode):
                res.append(node.text)
            elif isinstance(node, VarNode):
                res.append(self._render_expression(node.expression, ctx))
            elif isinstance(node, ForNode):
                res.append(self._render_for(node, ctx))
            elif isinstance(node, IfNode):
                res.append(self._render_if(node, ctx))
        return ''.join(res)

    def _get_var(self, name: str, ctx: dict):
        if '.' not in name:
            return ctx.get(name, None)

        parts = name.split('.')
        current = ctx.get(parts[0], None)
        if current is None:
            return None

        for part in parts[1:]:
            if isinstance(current, collections.abc.Mapping):
                if part in current:
                    current = current[part]
                else:
                    return None
            elif isinstance(current, (list, tuple)):
                try:
                    idx = int(part)
                    if 0 <= idx < len(current):
                        current = current[idx]
                    else:
                        return None
                except ValueError:
                    return None
            elif isinstance(current, str):
                # String attribute access? No, only name segments starting with non-_?
                # Prompt: "on any other value, with a name segment that does not start with _: the attribute"
                if not part.startswith('_'):
                    try:
                        current = getattr(current, part)
                    except AttributeError:
                        return None
                else:
                    return None
            else:
                return None
        return current

    def _render_expression(self, expr, ctx: dict):
        if isinstance(expr, VarName):
            return self._get_var(expr.name, ctx)
        elif isinstance(expr, StringLit):
            return expr.value
        elif isinstance(expr, IntLit):
            return expr.value
        elif isinstance(expr, FilteredValue):
            val = self._render_expression(expr.atom, ctx)
            for fname, arg in expr.filters:
                val = self._apply_filter(val, fname, arg)
            return val
        elif isinstance(expr, (ComparisonCond, NotCond, AndCond, OrCond)):
            # These should not be rendered directly in {{ }}. 
            raise TemplateRenderError("cannot render condition in output", 1)
        return None

    def _apply_filter(self, val, fname, arg):
        if fname == 'upper':
            if not isinstance(val, str):
                raise TemplateRenderError(f"upper requires string", 1)
            return val.upper()
        elif fname == 'lower':
            if not isinstance(val, str):
                raise TemplateRenderError(f"lower requires string", 1)
            return val.lower()
        elif fname == 'trim':
            if not isinstance(val, str):
                raise TemplateRenderError(f"trim requires string", 1)
            return val.strip()
        elif fname == 'length':
            return len(val) if val is not None else 0
        elif fname == 'first':
            if val is None or (isinstance(val, str) and val == '') or (isinstance(val, (list, tuple)) and len(val) == 0):
                return None
            return val[0]
        elif fname == 'last':
            if val is None or (isinstance(val, str) and val == '') or (isinstance(val, (list, tuple)) and len(val) == 0):
                return None
            return val[-1]
        elif fname == 'reverse':
            if val is None:
                return None
            if isinstance(val, str):
                return val[::-1]
            elif isinstance(val, (list, tuple)):
                return list(val)[::-1]
            raise TemplateRenderError("reverse requires string or list", 1)
        elif fname == 'join':
            if arg is None or not isinstance(arg, str):
                raise TemplateRenderError(f"join requires string argument", 1)
            if val is None:
                return ''
            if not isinstance(val, (list, tuple)):
                raise TemplateRenderError("join requires list", 1)
            return arg.join(str(item) for item in val)
        elif fname == 'default':
            if arg is None:
                raise TemplateRenderError("default requires argument", 1)
            if val is None or val == '':
                return arg
            return val
        elif fname == 'truncate':
            if arg is None or not isinstance(arg, int):
                raise TemplateRenderError("truncate requires integer argument", 1)
            if arg < 0:
                raise TemplateRenderError("truncate argument must be non-negative", 1)
            txt = str(val)
            if len(txt) > arg:
                return txt[:arg] + '...'
            return txt
        elif fname == 'items':
            if val is None:
                return []
            if not isinstance(val, collections.abc.Mapping):
                raise TemplateRenderError("items requires mapping", 1)
            return list(val.items())
        else:
            raise TemplateRenderError(f"unknown filter '{fname}'", 1)

    def _render_for(self, node: ForNode, ctx: dict) -> str:
        val = self._render_expression(node.expr, ctx)

        items = []
        if val is not None:
            if isinstance(val, collections.abc.Mapping):
                items = list(val.keys())
            elif hasattr(val, '__iter__') and not isinstance(val, str):
                items = list(val)
            else:
                raise TemplateRenderError("for requires iterable", node.lineno)

        if not items:
            return self._render_nodes(node.else_body, ctx)

        result = []
        for idx, item in enumerate(items):
            new_ctx = dict(ctx)
            new_ctx[node.name] = item
            new_ctx['loop'] = {
                'index': idx + 1,
                'index0': idx,
                'first': idx == 0,
                'last': idx == len(items) - 1,
                'length': len(items)
            }
            result.append(self._render_nodes(node.body, new_ctx))

        return ''.join(result)

    def _render_if(self, node: IfNode, ctx: dict) -> str:
        for cond_expr, body in node.branches:
            val = self._evaluate_condition(cond_expr, ctx)
            if val:
                return self._render_nodes(body, ctx)

        if node.else_body:
            return self._render_nodes(node.else_body, ctx)
        return ''

    def _evaluate_condition(self, expr, ctx):
        if isinstance(expr, ComparisonCond):
            left = self._render_expression(expr.left, ctx)
            right = self._render_expression(expr.right, ctx)
            try:
                if expr.op == '==': return left == right
                if expr.op == '!=': return left != right
                if expr.op == '<': return left < right
                if expr.op == '<=': return left <= right
                if expr.op == '>': return left > right
                if expr.op == '>=': return left >= right
            except TypeError:
                raise TemplateRenderError(f"cannot compare {type(left)} and {type(right)}", expr.left.lineno if hasattr(expr.left, 'lineno') else 1)
        elif isinstance(expr, NotCond):
            return not self._evaluate_condition(expr.expr, ctx)
        elif isinstance(expr, AndCond):
            left = self._evaluate_condition(expr.left, ctx)
            if not left:
                return False
            return self._evaluate_condition(expr.right, ctx)
        elif isinstance(expr, OrCond):
            left = self._evaluate_condition(expr.left, ctx)
            if left:
                return True
            return self._evaluate_condition(expr.right, ctx)
        elif isinstance(expr, (VarName, StringLit, IntLit, FilteredValue)):
            val = self._render_expression(expr, ctx)
            return bool(val)
        return False
