"""Dependency Graph for tracking cell references."""

from typing import Set


class DependencyGraph:
    def __init__(self):
        # precedents[cell] = set of cells that cell refers to
        self._precedents: dict[str, set[str]] = {}
        # dependents[cell] = set of cells that refer to cell
        self._dependents: dict[str, set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Set[str]) -> None:
        """Replace cell's precedents with the given set."""
        old_precedents = self._precedents.get(cell, set())

        # Update precedents map
        if precedents:
            self._precedents[cell] = set(precedents)
        else:
            if cell in self._precedents:
                del self._precedents[cell]

        # Update dependents map: remove cell from old dependents, add to new dependents
        # First, remove current cell from dependents of its old precedents
        for p in old_precedents:
            if p in self._dependents:
                self._dependents[p].discard(cell)
                if not self._dependents[p]:
                    del self._dependents[p]

        # Add current cell to dependents of its new precedents
        for p in precedents:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

    def precedents(self, cell: str) -> Set[str]:
        """Return the direct precedents of a cell."""
        return set(self._precedents.get(cell, set()))

    def dependents(self, cell: str) -> Set[str]:
        """Return the direct dependents of a cell."""
        return set(self._dependents.get(cell, set()))

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Return every cell that refers to cell directly or through other cells.
        Contains cell itself only when cell is on a cycle.
        """
        all_deps = set()
        queue = [cell]

        while queue:
            current = queue.pop(0)
            deps = self.dependents(current)
            for dep in deps:
                if dep not in all_deps:
                    all_deps.add(dep)
                    queue.append(dep)

        return all_deps

    def cycle_cells(self) -> Set[str]:
        """
        Return every cell that lies on a cycle.
        A cell is on a cycle if following precedents leads back to itself.
        """
        cycles = set()

        # For each cell, do a DFS to see if we can reach itself
        for start in set(self._precedents.keys()) | set(self._dependents.keys()):
            # BFS/DFS from start following precedents
            visited = set()
            stack = list(self._precedents.get(start, set()))

            while stack:
                node = stack.pop()
                if node == start:
                    cycles.add(start)
                    break
                if node in visited:
                    continue
                visited.add(node)
                stack.extend(self._precedents.get(node, set()))

        return cycles
