"""Sheet class managing cells, values, and recalculation."""

import re
from typing import Any

from .formula import (
    parse_formula, evaluate, references,
    FormulaError, ErrorValue, ERROR_CYCLE
)
from .graph import DependencyGraph


# Regex for optional minus followed by digits with optional decimal
NUM_REGEX = re.compile(r'^-?\d+(\.\d+)?$')


class Sheet:
    def __init__(self):
        self._raw: dict[str, str] = {}  # cell -> raw input string
        self._value: dict[str, Any] = {}  # cell -> computed value
        self._graph = DependencyGraph()
        self._evaluations: int = 0

    def _validate_name(self, name: str) -> str:
        """Validate and normalize cell name. Raises ValueError if invalid."""
        name = name.upper()
        # Check format: one letter A-Z, then digits 1-999, no leading zeros
        if len(name) < 2:
            raise ValueError(f"Invalid cell name: {name}")

        col = name[0]
        row_str = name[1:]

        if not col.isalpha() or col < 'A' or col > 'Z':
            raise ValueError(f"Invalid column in cell name: {name}")

        if not row_str.isdigit():
            raise ValueError(f"Invalid row in cell name: {name}")

        # No leading zeros
        if len(row_str) > 1 and row_str[0] == '0':
            raise ValueError(f"Leading zero in row number: {name}")

        row = int(row_str)
        if row < 1 or row > 999:
            raise ValueError(f"Row number out of range: {name}")

        return name

    def set(self, name: str, raw: Any) -> list[str]:
        """
        Set a cell's input. Returns list of cells whose value may have changed,
        in row-major order.
        """
        if not isinstance(raw, str):
            raise TypeError("Raw value must be a string")

        name = self._validate_name(name)

        # If raw is empty, empty the cell
        if raw == '':
            # Clear previous dependencies
            self._graph.set_dependencies(name, set())
            self._raw[name] = ''
            self._value.pop(name, None)

            # Calculate changed cells
            changed = self._get_changed_cells(name)
            self._recalculate(changed)
            return sorted(changed, key=self._row_major_key)

        # Determine type of input
        raw_stripped = raw.strip()

        if raw_stripped.startswith('='):
            # Formula
            try:
                formula_str = raw_stripped[1:]
                tree = parse_formula(formula_str)
            except FormulaError:
                raise FormulaError("Invalid formula")

            # Store raw
            self._raw[name] = raw

            # Update dependencies
            refs = references(tree)
            self._graph.set_dependencies(name, refs)

            # Invalidate value
            self._value.pop(name, None)

            # Calculate changed cells
            changed = self._get_changed_cells(name)
            self._recalculate(changed)
            return sorted(changed, key=self._row_major_key)
        else:
            # Check if it's a number
            if NUM_REGEX.match(raw_stripped):
                val = float(raw_stripped) if '.' in raw_stripped else int(raw_stripped)
                self._raw[name] = raw
                self._value[name] = val
                # Clear any previous formula dependencies
                self._graph.set_dependencies(name, set())

                changed = self._get_changed_cells(name)
                self._recalculate(changed)
                return sorted(changed, key=self._row_major_key)
            else:
                # Text
                self._raw[name] = raw
                self._value[name] = raw
                # Clear any previous formula dependencies
                self._graph.set_dependencies(name, set())

                changed = self._get_changed_cells(name)
                self._recalculate(changed)
                return sorted(changed, key=self._row_major_key)

    def _row_major_key(self, name: str) -> tuple[int, str]:
        """Sort key for row-major order."""
        col = name[0]
        row = int(name[1:])
        return (row, col)

    def _get_changed_cells(self, name: str) -> set[str]:
        """Get all cells that need recalculation after setting a cell."""
        # The cell itself plus all its dependents
        all_deps = self._graph.all_dependents(name)
        all_deps.add(name)
        return all_deps

    def _recalculate(self, cells_to_calc: set[str]) -> None:
        """
        Recalculate the given cells.
        Rules:
        1. Cells on cycles get #CYCLE!
        2. Evaluate in an order such that precedents are computed first.
        3. Each formula is evaluated exactly once.
        """
        # Determine cycle cells
        cycles = self._graph.cycle_cells()

        # Mark cells on cycles as #CYCLE!
        for cell in cells_to_calc:
            if cell in cycles:
                self._value[cell] = ERROR_CYCLE

        # Get non-cycle cells in cells_to_calc that are formulas
        calc_cells = [c for c in cells_to_calc if c not in cycles and self._raw.get(c, '').strip().startswith('=')]

        # Topological sort of calc_cells
        # Build a subgraph of calc_cells
        in_degree = {c: 0 for c in calc_cells}
        adj = {c: [] for c in calc_cells}

        for cell in calc_cells:
            precs = self._graph.precedents(cell)
            for p in precs:
                if p in calc_cells:
                    adj[p].append(cell)
                    in_degree[cell] = in_degree.get(cell, 0) + 1

        # Kahn's algorithm
        queue = [c for c in calc_cells if in_degree[c] == 0]
        sorted_cells = []

        while queue:
            node = queue.pop(0)
            sorted_cells.append(node)
            for neighbor in adj[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        # If there are remaining cells, they form a cycle within calc_cells
        # This shouldn't happen if cycle_cells() is correct and we removed all cycle cells
        if len(sorted_cells) < len(calc_cells):
            remaining = [c for c in calc_cells if c not in set(sorted_cells)]
            sorted_cells.extend(remaining)

        # Evaluate in order
        for cell in sorted_cells:
            raw = self._raw.get(cell, '')
            if not raw:
                continue

            raw_stripped = raw.strip()
            if not raw_stripped.startswith('='):
                continue

            try:
                formula_str = raw_stripped[1:]
                tree = parse_formula(formula_str)
            except FormulaError:
                continue

            # Lookup function
            def lookup(name: str) -> Any:
                return self._value.get(name, None)

            try:
                val = evaluate(tree, lookup)
            except Exception:
                val = ERROR_ERROR

            self._value[cell] = val
            self._evaluations += 1

    def get(self, name: str) -> Any:
        """Return the cell's value."""
        name = self._validate_name(name)
        return self._value.get(name, None)

    def raw(self, name: str) -> str:
        """Return the raw input for the cell."""
        name = self._validate_name(name)
        return self._raw.get(name, '')

    def cells(self) -> list[str]:
        """Return non-empty cells in row-major order."""
        non_empty = [name for name in self._raw if self._raw[name] != '']
        non_empty.sort(key=self._row_major_key)
        return non_empty

    @property
    def evaluations(self) -> int:
        return self._evaluations
