        # Operators and parens
        if src[i] in '+-*/()':
            tokens.append(('OP', src[i]))
            i += 1
            continue

        # Reference: Letter(s) followed by digits
        # We need to capture the contiguous block
        j = i
        while j < len(src) and src[j].isalnum():
            j += 1

        word = src[i:j]
        if not word:
            raise FormulaError(f"Unexpected character: {src[i]}")

        # Check if it's a valid reference (letter + digits) or a number
        # A reference starts with a letter
        if word[0].isalpha():
            # It might be a reference like A1, or an invalid one like AA1
            # Check if it matches the ref pattern: one letter, then digits
            if len(word) == 2 and word[1].isdigit():
                tokens.append(('REF', word.upper()))
            elif len(word) > 2 and word[1:].isdigit():
                # More than one letter? Or invalid ref?
                # Grammar says ref := letters digits. But constraint says max 1 letter column.
                # "a reference outside the sheet (more than one letter...)" raises error.
                # So if more than one letter, it's an error.
                tokens.append(('REF', word.upper()))
            else:
                raise FormulaError(f"Invalid token: {word}")
            i = j
            continue
        elif word[0].isdigit():
            # Number
            tokens.append(('NUM', word))
            i = j
            continue
        else:
            raise FormulaError(f"Unknown token: {word}")

    # Now parse the tokens into AST
    parser = _FormulaParser(tokens)
    ast = parser.parse()
    parser.check_end()
    return ast


class _FormulaParser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def parse(self):
        return self._expr()

    def check_end(self):
        if self.pos < len(self.tokens):
            raise FormulaError("Unexpected tokens after expression")

    def _expr(self):
        node = self._term()
        while self.peek() == ('OP', '+') or self.peek() == ('OP', '-'):
            op = self.advance()[1]
            right = self._term()
            node = BinaryOp(op, node, right)
        return node

    def _term(self):
        node = self._unary()
        while self.peek() == ('OP', '*') or self.peek() == ('OP', '/'):
            op = self.advance()[1]
            right = self._unary()
            node = BinaryOp(op, node, right)
        return node

    def _unary(self):
        if self.peek() == ('OP', '+') or self.peek() == ('OP', '-'):
            op = self.advance()[1]
            operand = self._unary()
            return UnaryOp(op, operand)
        return self._primary()

    def _primary(self):
        token = self.peek()

        if token is None:
            raise FormulaError("Unexpected end of expression")

        if token[0] == 'OP' and token[1] == '(':
            self.advance()  # consume (
            expr = self._expr()
            if not (self.peek() == ('OP', ')')):
                raise FormulaError("Unbalanced parentheses")
            self.advance()  # consume )
            return expr

        if token[0] == 'REF':
            self.advance()
            ref_name = token[1]
            if not _is_valid_ref(ref_name):
                raise FormulaError(f"Invalid reference: {ref_name}")
            return CellRef(ref_name)

        if token[0] == 'NUM':
            self.advance()
            num_str = token[1]
            if '.' in num_str:
                val = float(num_str)
            else:
                val = int(num_str)
            return Number(val)

        raise FormulaError(f"Unexpected token: {token}")


def references(tree: Any) -> set[str]:
    """Return the set of cell names referenced in the AST."""
    refs = set()
    if isinstance(tree, CellRef):
        refs.add(tree.name)
    elif isinstance(tree, UnaryOp):
        refs.update(references(tree.operand))
    elif isinstance(tree, BinaryOp):
        refs.update(references(tree.left))
        refs.update(references(tree.right))
    return refs


def evaluate(tree: Any, lookup) -> Any:
    """
    Evaluate the AST. `lookup` is a function name -> value.
    Returns the computed value, which may be an int, float, str, None, or ErrorValue.
    """
    if isinstance(tree, Number):
        return tree.value

    if isinstance(tree, CellRef):
        val = lookup(tree.name)
        # If the formula is just a reference, return the value as is.
        # The conversion of None to 0 happens in BinaryOp/UnaryOp handlers.
        return val

    if isinstance(tree, UnaryOp):
        val = evaluate(tree.operand, lookup)
        # If val is error, return it
        if isinstance(val, ErrorValue):
            return val

        # Handle None -> 0 for unary ops
        if val is None:
            val = 0

        if isinstance(val, str):
            return ERROR_ERROR

        if not isinstance(val, (int, float)):
            return ERROR_ERROR

        if tree.op == '+':
            return val
        else:  # -
            return -val

    if isinstance(tree, BinaryOp):
        left = evaluate(tree.left, lookup)
        right = evaluate(tree.right, lookup)

        # Propagate errors
        if isinstance(left, ErrorValue):
            return left
        if isinstance(right, ErrorValue):
            return right

        # Convert None to 0 for operands
        if left is None:
            left = 0
        if right is None:
            right = 0

        # Check for text
        if isinstance(left, str) or isinstance(right, str):
            return ERROR_ERROR

        # Check for valid numeric types
        if not isinstance(left, (int, float)) or not isinstance(right, (int, float)):
            return ERROR_ERROR

        op = tree.op

        if op == '+':
            # int + int -> int, else float
            if isinstance(left, int) and isinstance(right, int):
                return left + right
            return float(left) + float(right)
        elif op == '-':
            if isinstance(left, int) and isinstance(right, int):
                return left - right
            return float(left) - float(right)
        elif op == '*':
            if isinstance(left, int) and isinstance(right, int):
                return left * right
            return float(left) * float(right)
        elif op == '/':
            if right == 0:
                return ERROR_ERROR
            return float(left) / float(right)

    raise FormulaError("Unknown AST node")
