# calc.py

from fractions import Fraction


class CalcError(Exception):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.position = position


def tokenize(expr: str):
    """
    Generator that yields (token_type, value, position) tuples.
    Token types: 'NUM', 'OP', 'LPAREN', 'RPAREN'
    Raises CalcError with position on invalid syntax.
    """
    i = 0
    n = len(expr)

    while i < n:
        char = expr[i]

        # Skip whitespace
        if char in ' \t':
            i += 1
            continue

        # Check for unknown characters
        if char not in '0123456789.+-*/()':
            raise CalcError(f"Unexpected character '{char}'", i)

        # Parentheses
        if char == '(':
            yield ('LPAREN', '(', i)
            i += 1
            continue
        if char == ')':
            yield ('RPAREN', ')', i)
            i += 1
            continue

        # Operators
        if char in '+-*/':
            yield ('OP', char, i)
            i += 1
            continue

        # Numbers
        if char.isdigit():
            start_pos = i
            # Parse digits
            while i < n and expr[i].isdigit():
                i += 1

            # Check for decimal point
            if i < n and expr[i] == '.':
                i += 1  # skip the dot
                if i >= n or not expr[i].isdigit():
                    # No digits after the dot -> invalid, e.g., '5.'
                    raise CalcError("Invalid number format: no digits after decimal point", start_pos)

                # Parse digits after the dot
                while i < n and expr[i].isdigit():
                    i += 1

            # The number is complete
            num_str = expr[start_pos:i]
            yield ('NUM', num_str, start_pos)
            continue

        # This should not be reached if all characters are handled above
        raise CalcError(f"Unexpected character '{char}'", i)


def evaluate(expr: str) -> Fraction:
    """
    Evaluates an arithmetic expression and returns a Fraction.
    Raises CalcError on syntax errors or division by zero.
    """
    token_iter = iter(tokenize(expr))
    n = len(expr)

    def peek():
        try:
            return next(token_iter)
        except StopIteration:
            return ('EOF', None, n)

    def consume():
        return next(token_iter)

    def parse_expression():
        left = parse_term()

        while True:
            token = peek()
            if token[0] == 'OP' and token[1] in '+-':
                op = consume()
                right = parse_term()
                if op[1] == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break

        return left

    def parse_term():
        left = parse_factor()

        while True:
            token = peek()
            if token[0] == 'OP' and token[1] in '*/':
                op = consume()
                right = parse_factor()
                if op[1] == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise CalcError("Division by zero", op[2])
                    left = left / right
            else:
                break

        return left

    def parse_factor():
        token = peek()

        if token[0] == 'OP' and token[1] == '-':
            consume()
            operand = parse_factor()
            return -operand
        elif token[0] == 'LPAREN':
            consume()
            result = parse_expression()
            token = peek()
            if token[0] != 'RPAREN':
                if token[0] == 'EOF':
                    raise CalcError("Unexpected end of input", n)
                else:
                    raise CalcError(f"Expected ')' but got '{token[1]}'", token[2])
            consume()  # Consume RPAREN
            return result
        elif token[0] == 'NUM':
            consume()
            return Fraction(token[1])
        else:
            if token[0] == 'EOF':
                raise CalcError("Unexpected end of input", n)
            else:
                raise CalcError(f"Unexpected token '{token[1]}'", token[2])

    result = parse_expression()

    # Check for extra tokens
    token = peek()
    if token[0] != 'EOF':
        raise CalcError(f"Unexpected token '{token[1]}'", token[2])

    return result


if __name__ == '__main__':
    # Test cases
    # Test 1: Basic decimal arithmetic
    result = evaluate('0.1 + 0.2')
    assert result == Fraction(3, 10), f"Expected Fraction(3, 10), got {result}"
    print("Test 1 passed: evaluate('0.1 + 0.2') == Fraction(3, 10)")

    # Test 2: Syntax error at position 4
    try:
        evaluate('1 + * 2')
        assert False, "Should have raised CalcError"
    except CalcError as e:
        assert e.position == 4, f"Expected position 4, got {e.position}"
        print("Test 2 passed: evaluate('1 + * 2') raises CalcError at position 4")

    # Test 3: Unary minus
    result = evaluate('-3 * 2')
    assert result == Fraction(-6, 1), f"Expected -6, got {result}"
    print("Test 3 passed: evaluate('-3 * 2') == Fraction(-6, 1)")

    # Test 4: Double unary minus
    result = evaluate('--4')
    assert result == Fraction(4, 1), f"Expected 4, got {result}"
    print("Test 4 passed: evaluate('--4') == Fraction(4, 1)")

    # Test 5: Division by zero
    try:
        evaluate('1 + 4 / (2 - 2)')
        assert False, "Should have raised CalcError"
    except CalcError as e:
        assert e.position == 6, f"Expected position 6, got {e.position}"
        print("Test 5 passed: evaluate('1 + 4 / (2 - 2)') raises CalcError at position 6")

    # Test 6: Empty string
    try:
        evaluate('')
        assert False, "Should have raised CalcError"
    except CalcError as e:
        assert e.position == 0, f"Expected position 0, got {e.position}"
        print("Test 6 passed: evaluate('') raises CalcError at position 0")

    print("\nAll tests passed!")
