            return Fraction(token[1])
        else:
            if token[0] == 'EOF':
                raise CalcError("Unexpected end of input", n)
            else:
                raise CalcError(f"Unexpected token '{token[1]}'", token[2])

    result = parse_expression()

    # Check for extra tokens
    token = peek()
    if token[0] != 'EOF':
        raise CalcError(f"Unexpected token '{token[1]}'", token[2])

    return result


if __name__ == '__main__':
    # Test cases
    # Test 1: Basic decimal arithmetic
    result = evaluate('0.1 + 0.2')
    assert result == Fraction(3, 10), f"Expected Fraction(3, 10), got {result}"
    print("Test 1 passed: evaluate('0.1 + 0.2') == Fraction(3, 10)")

    # Test 2: Syntax error at position 4
    try:
        evaluate('1 + * 2')
        assert False, "Should have raised CalcError"
    except CalcError as e:
        assert e.position == 4, f"Expected position 4, got {e.position}"
        print("Test 2 passed: evaluate('1 + * 2') raises CalcError at position 4")

    # Test 3: Unary minus
    result = evaluate('-3 * 2')
    assert result == Fraction(-6, 1), f"Expected -6, got {result}"
    print("Test 3 passed: evaluate('-3 * 2') == Fraction(-6, 1)")

    # Test 4: Double unary minus
    result = evaluate('--4')
    assert result == Fraction(4, 1), f"Expected 4, got {result}"
    print("Test 4 passed: evaluate('--4') == Fraction(4, 1)")

    # Test 5: Division by zero
    try:
        evaluate('1 + 4 / (2 - 2)')
        assert False, "Should have raised CalcError"
    except CalcError as e:
        assert e.position == 6, f"Expected position 6, got {e.position}"
        print("Test 5 passed: evaluate('1 + 4 / (2 - 2)') raises CalcError at position 6")

    # Test 6: Empty string
    try:
        evaluate('')
        assert False, "Should have raised CalcError"
    except CalcError as e:
        assert e.position == 0, f"Expected position 0, got {e.position}"
        print("Test 6 passed: evaluate('') raises CalcError at position 0")

    print("\nAll tests passed!")

""""Renderer for the tmpl template engine.

Handles variable resolution, filter application, condition evaluation,
control flow (for loops, if/elif/else), and AST traversal to produce
the final rendered output string.
"""

from collections.abc import Mapping
from typing import Any

from tmpl.lexer import TemplateError, TemplateSyntaxError, TemplateRenderError
from tmpl.parser import (
    Atom,
    Condition,
    Expression,
    ForLoopNode,
    IfBlockNode,
    Node,
    OutputNode,
    TextNode,
    parse,
)


# ---------------------------------------------------------------------------
# Variable resolution
# ---------------------------------------------------------------------------

def _resolve_atom(atom: Atom, context: dict) -> Any:
    """Resolve an Atom to its value in the given context."""
    if atom.kind == "str":
        return atom.value
    if atom.kind == "int":
        return atom.value
    # var
    parts = atom.value.split(".")
    current: Any = context.get(parts[0]) if parts[0] in context else None
    for seg in parts[1:]:
        if current is None:
            return None
        if isinstance(current, Mapping):
            current = current.get(seg)
        elif isinstance(current, (list, tuple)):
            try:
                idx = int(seg)
            except ValueError:
                current = None
                break
            if 0 <= idx < len(current):
                current = current[idx]
            else:
                current = None
                break
        elif not seg.startswith("_"):
            current = getattr(current, seg, None)
        else:
            current = None
            break
    return current


def _apply_filters(value: Any, filters: list[tuple[str, Any | None]], lineno: int) -> Any:
    """Apply a sequence of filters to a value, returning the result."""
    for filter_name, arg in filters:
        if filter_name == "upper":
            if arg is not None:
                raise TemplateSyntaxError("upper takes no arguments", lineno)
            output_text = _to_output_text(value)
            value = output_text.upper()
        elif filter_name == "lower":
            if arg is not None:
                raise TemplateSyntaxError("lower takes no arguments", lineno)
            output_text = _to_output_text(value)
            value = output_text.lower()
        elif filter_name == "trim":
            if arg is not None:
                raise TemplateSyntaxError("trim takes no arguments", lineno)
            output_text = _to_output_text(value)
            value = output_text.strip()
        elif filter_name == "length":
            if arg is not None:
                raise TemplateSyntaxError("length takes no arguments", lineno)
            if value is None:
                value = 0
            else:
                try:
                    value = len(value)
                except TypeError:
                    raise TemplateRenderError(
                        f"cannot compute length of {type(value).__name__}", lineno
                    ) from None
        elif filter_name == "first":
            if arg is not None:
                raise TemplateSyntaxError("first takes no arguments", lineno)
            if value is None or (isinstance(value, str) and value == "") or (hasattr(value, "__len__") and len(value) == 0):
                value = None
            else:
                if isinstance(value, str):
                    value = value[0]
                else:
                    value = value[0]
        elif filter_name == "last":
            if arg is not None:
                raise TemplateSyntaxError("last takes no arguments", lineno)
            if value is None or (isinstance(value, str) and value == "") or (hasattr(value, "__len__") and len(value) == 0):
                value = None
            else:
                if isinstance(value, str):
                    value = value[-1]
                else:
                    value = value[-1]
        elif filter_name == "reverse":
            if arg is not None:
                raise TemplateSyntaxError("reverse takes no arguments", lineno)
            if value is None:
                value = None
            elif isinstance(value, str):
                value = value[::-1]
            elif isinstance(value, (list, tuple)):
                value = value[::-1]
            else:
                raise TemplateRenderError(
                    f"cannot reverse {type(value).__name__}", lineno
                ) from None
        elif filter_name == "join":
            if arg is None or not isinstance(arg, str):
                raise TemplateSyntaxError("join requires a string argument", lineno)
            if value is None:
                value = ""
            else:
                output_parts = [\_to_output_text(item) for item in value]
                value = arg.join(output_parts)
        elif filter_name == "default":
            if arg is None:
                raise TemplateSyntaxError("default requires an argument", lineno)
            if value is None or value == "":
                value = arg
        elif filter_name == "truncate":
            if arg is None:
                raise TemplateSyntaxError("truncate requires an integer argument", lineno)
            if not isinstance(arg, int) or isinstance(arg, bool) or arg < 0:
                raise TemplateSyntaxError("truncate requires a non-negative integer argument", lineno)
            output_text = _to_output_text(value)
            if len(output_text) > arg:
                value = output_text[:arg] + "..."
            else:
                value = output_text
        elif filter_name == "items":
            if arg is not None:
                raise TemplateSyntaxError("items takes no arguments", lineno)
            if value is None:
                value = []
            elif isinstance(value, Mapping):
                value = list(value.items())
            else:
                raise TemplateRenderError(
                    f"items filter requires a mapping", lineno
                ) from None
        else:
            raise TemplateSyntaxError(f"unknown filter: {filter_name}", lineno)
    return value


def _to_output_text(value: Any) -> str:
    """Convert a value to its output text representation."""
    if value is None:
        return ""
    return str(value)


# ---------------------------------------------------------------------------
# Condition evaluation
# ---------------------------------------------------------------------------

def _eval_condition(cond: Condition, context: dict, lineno: int) -> bool:
    """Evaluate a condition tree with correct precedence and short-circuiting."""
    # First, evaluate the left-hand value
    left_val = _eval_value_expression(cond.value, context, lineno)

    if cond.op is None:
        # bare value expression
        return bool(left_val)

    if cond.op == "not":
        return not _eval_value_expression(cond.right, context, lineno) if cond.right else not bool(left_val)

    # For 'and', 'or', comparison operators, evaluate right side only if needed
    if cond.op == "and":
        if not left_val:
            return False
        return bool(_eval_value_expression(cond.right, context, lineno))

    if cond.op == "or":
        if left_val:
            return True
        return bool(_eval_value_expression(cond.right, context, lineno))

    # Comparison operators
    right_val = _eval_value_expression(cond.right, context, lineno)
    try:
        if cond.op == "==":
            return left_val == right_val
        if cond.op == "!=":
            return left_val != right_val
        if cond.op == "<":
            if left_val is None or right_val is None:
                raise TemplateRenderError("cannot compare None with non-None values", lineno)
            return left_val < right_val
        if cond.op == "<=":
            if left_val is None or right_val is None:
                raise TemplateRenderError("cannot compare None with non-None values", lineno)
            return left_val <= right_val
        if cond.op == ">":
            if left_val is None or right_val is None:
                raise TemplateRenderError("cannot compare None with non-None values", lineno)
            return left_val > right_val
        if cond.op == ">=":
            if left_val is None or right_val is None:
                raise TemplateRenderError("cannot compare None with non-None values", lineno)
            return left_val >= right_val
    except TypeError as e:
        raise TemplateRenderError(str(e), lineno) from None

    raise TemplateRenderError(f"unknown operator: {cond.op}", lineno)


def _eval_value_expression(expr: Expression, context: dict, lineno: int) -> Any:
    """Evaluate a value expression (atom + filters)."""
    value = _resolve_atom(expr.atom, context)
    if expr.filters:
        value = _apply_filters(value, expr.filters, lineno)
    return value


# ---------------------------------------------------------------------------
# AST traversal / rendering
# ---------------------------------------------------------------------------

def _render_nodes(nodes: list[Node], context: dict, lineno_map: dict | None) -> str:
    """Render a list of AST nodes against the given context."""
    parts: list[str] = []
    for node in nodes:
        if isinstance(node, TextNode):
            parts.append(node.text)
        elif isinstance(node, OutputNode):
            value = _eval_value_expression(node.expr, context, node.lineno)
            parts.append(_to_output_text(value))
        elif isinstance(node, ForLoopNode):
            result = _render_for(node, context)
            parts.append(result)
        elif isinstance(node, IfBlockNode):
            result = _render_if(node, context)
            parts.append(result)
    return "".join(parts)


def _render_for(node: ForLoopNode, context: dict) -> str:
    """Render a for loop."""
    items = _eval_value_expression(node.expr, context, node.lineno)

    # Build the loop metadata mapping
    try:
        items_list = list(items)
    except TypeError:
        raise TemplateRenderError(
            f"cannot iterate over {type(items).__name__}", node.lineno
        ) from None

    loop_meta: dict[str, Any] = {
        "index": 0,
        "index0": 0,
        "first": True,
        "last": len(items_list) == 1,
        "length": len(items_list),
    }

    old_loop = context.get("loop")
    old_name_val = context.get(node.name)

    try:
        context["loop"] = loop_meta

        if not items_list:
            if node.orelse:
                return _render_nodes(node.orelse, context, None)
            return ""

        parts: list[str] = []
        for i, item in enumerate(items_list):
            context[node.name] = item
            loop_meta["index"] = i + 1
            loop_meta["index0"] = i
            loop_meta["first"] = i == 0
            loop_meta["last"] = i == len(items_list) - 1
            parts.append(_render_nodes(node.body, context, None))

        return "".join(parts)
    finally:
        if old_loop is not None:
            context["loop"] = old_loop
        elif "loop" in context:
            del context["loop"]
        if old_name_val is not None:
            context[node.name] = old_name_val
        elif node.name in context:
            del context[node.name]


def _render_if(node: IfBlockNode, context: dict) -> str:
    """Render an if/elif/else block."""
    for cond, body in node.conditions:
        if _eval_condition(cond, context, cond.lineno):
            return _render_nodes(body, context, None)
    if node.orelse:
        return _render_nodes(node.orelse, context, None)
    return ""


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------


class Template:
    """A parsed template ready for rendering.

    The constructor parses the source immediately, so any syntax errors
    are raised at construction time.
    """

    def __init__(self, source: str) -> None:
        self._nodes: list[Node] = parse(source)

    def render(self, context: dict | None = None, **kwargs) -> str:
        """Render the template against the given context.

        The context is a dictionary mapping names to values. Keyword arguments
        override context entries with the same name. The context dict is never
        modified.

        Returns the rendered string.
        """
        # Build a new context dict to avoid modifying the original
        ctx: dict[str, Any] = {}
        if context:
            ctx.update(context)
        ctx.update(kwargs)

        return _render_nodes(self._nodes, ctx, None)


def render(source: str, context: dict | None = None, **kwargs) -> str:
    """Convenience function: parse and render a template in one call.

    Equivalent to ``Template(source).render(context, **kwargs)``.
    """
    return Template(source).render(context, **kwargs)
