class ErrorValue(str):
    pass


def _error_error():
    return ErrorValue("#ERROR!")


def _error_cycle():
    return ErrorValue("#CYCLE!")


class FormulaError(ValueError):
    pass


class _Node:
    pass


class _Num(_Node):
    def __init__(self, val):
        self.val = val


class _Ref(_Node):
    def __init__(self, name):
        self.name = name


class _BinOp(_Node):
    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right


class _UnaryOp(_Node):
    def __init__(self, op, operand):
        self.op = op
        self.operand = operand


def _parse_number(tokens, pos):
    start = pos
    if pos >= len(tokens):
        return None, pos

    if tokens[pos] == '.':
        pos += 1
        if pos >= len(tokens) or tokens[pos] not in '0123456789':
            return None, pos
        while pos < len(tokens) and tokens[pos].isdigit():
            pos += 1
        return float(tokens[start:pos]), pos
    else:
        while pos < len(tokens) and tokens[pos].isdigit():
            pos += 1
        if pos == start:
            return None, pos
        num_str = tokens[start:pos]
        if '.' in num_str:
            return float(num_str), pos
        else:
            return int(num_str), pos


def _parse_ref(tokens, pos):
    start = pos
    while pos < len(tokens) and tokens[pos].isalpha():
        pos += 1
    letters_end = pos

    if pos >= len(tokens) or not tokens[pos].isdigit():
        return None, None, pos

    digit_start = pos
    while pos < len(tokens) and tokens[pos].isdigit():
        pos += 1

    col_str = tokens[start:letters_end]
    row_str = tokens[digit_start:pos]

    if len(col_str) != 1:
        return None, None, pos

    col = col_str.upper()
    if col < 'A' or col > 'Z':
        return None, None, pos

    # Check for leading zeros in row
    if len(row_str) > 1 and row_str[0] == '0':
        raise FormulaError(f"Row has leading zeros: {col_str}{row_str}")

    row = int(row_str)
    if row <= 0 or row > 999:
        raise FormulaError(f"Row out of range: {row}")

    name = f"{col}{row}"
    return name, name, pos


def _parse_primary(tokens, pos):
    if pos >= len(tokens):
        return None, pos

    tok = tokens[pos]

    if tok == '(': 
        pos += 1
        node, pos = _parse_expr(tokens, pos)
        if pos >= len(tokens) or tokens[pos] != ')':
            raise FormulaError("Unbalanced parentheses")
        pos += 1
        return node, pos

    if tok == '+': 
        return None, pos

    if tok == '-': 
        return None, pos

    if tok in '+-':
        pos += 1
        operand, pos = _parse_unary(tokens, pos)
        return _UnaryOp(tok, operand), pos

    if tok.isdigit() or tok == '.':
        val, new_pos = _parse_number(tokens, pos)
        if val is None:
            raise FormulaError("Invalid number")
        return _Num(val), new_pos

    if tok.isalpha():
        name, uc_name, new_pos = _parse_ref(tokens, pos)
        if uc_name is None:
            raise FormulaError(f"Invalid reference: {tok}")
        return _Ref(uc_name), new_pos

    raise FormulaError(f"Unexpected token: {tok}")


def _parse_unary(tokens, pos):
    if pos >= len(tokens):
        raise FormulaError("Expected expression")

    tok = tokens[pos]
    if tok == '+' or tok == '-':
        pos += 1
        operand, pos = _parse_unary(tokens, pos)
        return _UnaryOp(tok, operand), pos
    else:
        return _parse_primary(tokens, pos)


def _parse_term(tokens, pos):
    node, pos = _parse_unary(tokens, pos)
    while pos < len(tokens) and tokens[pos] in ('*', '/'):
        op = tokens[pos]
        pos += 1
        right, pos = _parse_unary(tokens, pos)
        node = _BinOp(op, node, right)
    return node, pos


def _parse_expr(tokens, pos):
    node, pos = _parse_term(tokens, pos)
    while pos < len(tokens) and tokens[pos] in ('+', '-'):
        op = tokens[pos]
        pos += 1
        right, pos = _parse_term(tokens, pos)
        node = _BinOp(op, node, right)
    return node, pos


def parse_formula(source: str):
    if not source or not source.strip():
        raise FormulaError("Empty formula")

    source = source.strip()

    # Tokenize: keep letters, digits, '.', '+', '-', '*', '/', '(' and ')'
    # Whitespace is ignored but we split by it
    # Actually, we can just remove whitespace and parse char by char
    # But references are case insensitive letters followed by digits.
    # Let's tokenize properly.

    tokens = []
    i = 0
    s = source
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c in '+-*/.()':
            tokens.append(c)
            i += 1
        elif c.isalpha():
            start = i
            while i < len(s) and s[i].isalpha():
                i += 1
            tokens.append(s[start:i])
        elif c.isdigit():
            start = i
            while i < len(s) and s[i].isdigit():
                i += 1
            tokens.append(s[start:i])
        else:
            raise FormulaError(f"Invalid character: {c}")

    if not tokens:
        raise FormulaError("Empty formula")

    node, pos = _parse_expr(tokens, 0)

    if pos != len(tokens):
        raise FormulaError("Incomplete expression")

    return node


def references(tree):
    refs = set()

    def walk(node):
        if isinstance(node, _Ref):
            refs.add(node.name)
        elif isinstance(node, _BinOp):
            walk(node.left)
            walk(node.right)
        elif isinstance(node, _UnaryOp):
            walk(node.operand)
        # _Num has no refs

    walk(tree)
    return refs


def _is_error(val):
    return isinstance(val, ErrorValue)


def evaluate(tree, lookup):
    def _eval_node(node):
        if isinstance(node, _Num):
            return node.val

        if isinstance(node, _Ref):
            val = lookup(node.name)
            if val is None:
                return 0
            if _is_error(val):
                return val
            if isinstance(val, str):
                return val
            return val

        if isinstance(node, _UnaryOp):
            op = node.op
            operand_val = _eval_node(node.operand)
            if _is_error(operand_val):
                return operand_val
            if isinstance(operand_val, str):
                return _error_error()
            try:
                if op == '+':
                    return operand_val
                else:
                    return -operand_val
            except:
                return _error_error()

        if isinstance(node, _BinOp):
            op = node.op
            left_val = _eval_node(node.left)
            right_val = _eval_node(node.right)

            if _is_error(left_val):
                return left_val
            if _is_error(right_val):
                return right_val

            # Type check
            # If either is string (and not error, which is handled), it's an error
            if isinstance(left_val, str) or isinstance(right_val, str):
                return _error_error()

            # Check for None? No, references return 0 if None, so we shouldn't get None here
            # unless a formula evaluates to None? No, formulas always evaluate to something.
            if left_val is None or right_val is None:
                return _error_error()

            if op == '+':
                if isinstance(left_val, int) and isinstance(right_val, int):
                    return left_val + right_val
                else:
                    return float(left_val) + float(right_val)
            elif op == '-':
                if isinstance(left_val, int) and isinstance(right_val, int):
                    return left_val - right_val
                else:
                    return float(left_val) - float(right_val)
            elif op == '*':
                if isinstance(left_val, int) and isinstance(right_val, int):
                    return left_val * right_val
                else:
                    return float(left_val) * float(right_val)
            elif op == '/':
                # Always float
                f_left = float(left_val)
                f_right = float(right_val)
                if f_right == 0:
                    return _error_error()
                return f_left / f_right

        raise FormulaError("Unknown node type")

    return _eval_node(tree)

