        self._evaluations: int = 0

    def _get_cell_content(self, name: str) -> Tuple[str, Any]:
        """Return (type, content) for a cell's raw input.

        Type is one of 'formula', 'number', 'text', 'empty'.
        Content is the parsed tree (for formula) or value (for number/text).
        """
        raw = self._raw.get(name, '')

        if not raw:
            return ('empty', None)

        stripped = raw.strip()

        if stripped.startswith('='):
            # It's a formula
            try:
                tree = parse_formula(stripped[1:])
                return ('formula', tree)
            except FormulaError:
                raise  # Re-raise

        if _is_valid_number_str(stripped):
            if '.' in stripped:
                val = float(stripped)
            else:
                val = int(stripped)
            return ('number', val)

        return ('text', raw)

    def set(self, name: str, raw: Any) -> List[str]:
        """Store the cell's input and trigger recalculation.

        Args:
            name: Cell name (e.g., 'A1').
            raw: Raw input string. If empty string, cell is emptied.
                If starts with '=', it's a formula.
                Otherwise, if it matches number pattern, it's a number.
                Else, it's text.

        Returns:
            List of cell names whose values may have changed, in row-major order.

        Raises:
            TypeError: If raw is not a string.
            ValueError: If name is invalid.
            FormulaError: If raw is a formula with syntax error.
        """
        if not isinstance(raw, str):
            raise TypeError("raw must be a string")

        cell_name = _parse_cell_name(name)

        # Determine content type and parse if necessary
        # We do this before modifying state so we can raise FormulaError safely
        try:
            content_type, content_val = self._get_cell_content_raw(cell_name, raw)
        except FormulaError:
            raise

        # Update graph and raw
        self._raw[cell_name] = raw

        precedents: Set[str] = set()
        if content_type == 'formula':
            refs = references(content_val)
            self._graph.set_dependencies(cell_name, refs)
            precedents = refs
        else:
            self._graph.set_dependencies(cell_name, [])

        # Determine affected cells
        affected_cells = {cell_name}
        affected_cells.update(self._graph.all_dependents(cell_name))

        # Identify cycle cells globally
        cycle_cells = self._graph.cycle_cells()

        # Topological sort of affected cells
        # We need to evaluate precedents before dependents
        sorted_affected = self._topological_sort(affected_cells)

        # Evaluate/Update values
        for c in sorted_affected:
            if c in cycle_cells:
                self._values[c] = ErrorValue('#CYCLE!')
                continue

            raw_c = self._raw.get(c, '')

            if c == cell_name:
                # Update the set cell
                if content_type == 'formula':
                    try:
                        result = evaluate(content_val, self._get_value)
                        self._values[c] = result
                        self._evaluations += 1
                    except FormulaError:
                        self._values[c] = ErrorValue('#ERROR!')
                        self._evaluations += 1
                elif content_type == 'number':
                    self._values[c] = content_val
                elif content_type == 'text':
                    self._values[c] = content_val
                else: # empty
                    self._values[c] = None
            else:
                # Update dependents
                if raw_c.startswith('='):
                    try:
                        # Re-parse to get tree? Or store tree in a separate dict?
                        # Storing tree in memory might be heavy but spec doesn't forbid it. 
                        # However, spec says "evaluates each formula cell... exactly once".
                        # Let's store the trees in a separate dict for efficiency.
                        tree = self._parse_formula_once(raw_c[1:])
                        result = evaluate(tree, self._get_value)
                        self._values[c] = result
                        self._evaluations += 1
                    except FormulaError:
                        self._values[c] = ErrorValue('#ERROR!')
                        self._evaluations += 1
                # If it's text/number, value doesn't change based on precedents, so skip.

        return _sort_row_major(list(affected_cells))

    def _get_cell_content_raw(self, name: str, raw: str) -> Tuple[str, Any]:
        """Helper to parse content without accessing internal state."""
        if not raw:
            return ('empty', None)

        stripped = raw.strip()

        if stripped.startswith('='):
            tree = parse_formula(stripped[1:])
            return ('formula', tree)

        if _is_valid_number_str(stripped):
            if '.' in stripped:
                val = float(stripped)
            else:
                val = int(stripped)
            return ('number', val)

        return ('text', raw)

    def _get_value(self, name: str) -> Any:
        """Lookup a cell's current value."""
        return self._values.get(name, None)

    def _parse_formula_once(self, source: str) -> Any:
        """Parse formula and cache tree. (Optional optimization)"""
        # Since we re-parse in evaluate, let's just parse it.
        # To avoid re-parsing, we could cache. But for simplicity:
        return parse_formula(source)

    def _topological_sort(self, cells: Set[str]) -> List[str]:
        """Sort cells such that precedents come before dependents."""
        # Build adjacency list for the subgraph
        # Edge u -> v means u is a precedent of v
        in_degree: Dict[str, int] = {c: 0 for c in cells}
        adj: Dict[str, Set[str]] = {c: set() for c in cells}

        for c in cells:
            preds = self._graph.precedents(c)
            for p in preds:
                if p in cells:
                    adj[p].add(c)
                    in_degree[c] += 1

        # Kahn's algorithm
        queue = [c for c in cells if in_degree[c] == 0]
        result = []

        while queue:
            # Sort for deterministic order? Spec doesn't require, but helpful.
            queue.sort()
            u = queue.pop(0)
            result.append(u)

            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return result

    def get(self, name: str) -> Any:
        """Return the cell's value."""
        cell_name = _parse_cell_name(name)
        return self._values.get(cell_name, None)

    def raw(self, name: str) -> str:
        """Return the input last stored."""
        cell_name = _parse_cell_name(name)
        return self._raw.get(cell_name, '')

    def cells(self) -> List[str]:
        """Return the non-empty cells in row-major order."""
        non_empty = [c for c, v in self._values.items() if v is not None]
        return _sort_row_major(non_empty)

    @property
    def evaluations(self) -> int:
        """How many times a formula has been evaluated."""
        return self._evaluations
